  const shortDate=x=>new Intl.DateTimeFormat('mk-MK',{day:'2-digit',month:'short',timeZone:'UTC'}).format(new Date(x+'T12:00:00Z')).replace(/\.$/,'');
  const compactTerm=x=>String(x||'').replace('Вторник','Вто').replace('Четврток','Чет').replace(/:00/g,'');
